// Новые файлы без дубликатов. Пустой список — workflow на этом заканчивается.
const envelope = $input.first().json;
if (!envelope.ok) {
  throw new Error(`incoming.list: ${JSON.stringify(envelope.error)}`);
}
return envelope.data.items
  .filter(item => item.duplicate_of === null)
  .map(item => ({ json: { path: item.path } }));

// Итог приёма для слоя уведомлений. Состояние берётся из ответа Stocker, не вычисляется здесь.
const results = $input.all().map(item => {
  const e = item.json;
  return {
    asset_id: e.asset_id,
    ok: e.ok,
    outcome: e.outcome,
    error: e.error ? e.error.code : null,
    state: e.data && e.data.pipeline ? e.data.pipeline.metadata : null,
    reasons: e.data && e.data.pipeline ? e.data.pipeline.review_reasons : [],
  };
});
const failed = results.filter(r => !r.ok);
const review = results.filter(r => r.state === 'human_review');
const ready = results.filter(r => r.state === 'auto_approved');
const lines = [
  `Обработано новых файлов: ${results.length}`,
  `Готово автоматически: ${ready.length}`,
  `Ждут проверки: ${review.length}` + (review.length ? ` (${review.map(r => `#${r.asset_id} ${r.reasons.join(', ')}`).join('; ')})` : ''),
  `Ошибки: ${failed.length}` + (failed.length ? ` (${failed.map(r => `#${r.asset_id} ${r.error || r.outcome}`).join('; ')})` : ''),
];
return [{ json: {
  severity: failed.length ? 'warning' : review.length ? 'attention' : 'info',
  title: 'Stocker: новые фотографии',
  text: lines.join('\n'),
  data: { results },
} }];
